WITH parsed AS (SELECT id, service, host, latency_ms, status_code, payload_json, COALESCE(context['trace'], 'unknown') AS trace_or_default, SHIFTRIGHT(status_code, 2) AS status_code_high, ARRAY_CONTAINS(MAP_KEYS(context), 'version') AS has_version, context['trace'] AS trace FROM app_logs) SELECT id, service, host, latency_ms, status_code, trace_or_default, trace, MIN(status_code_high) OVER w_running AS running_min_status_code_high, MAX(status_code_high) OVER w_running AS running_max_status_code_high, COUNT(status_code_high) OVER w_running AS running_count_status_code_high FROM parsed WINDOW w_running AS (PARTITION BY host ORDER BY latency_ms, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
